    ground_rows = set()
    for r, c in markers:
        if r - 2 >= 0:
            for x in range(max(0, c - 2), min(w, c + 3)):
                out[r - 2][x] = 5
        for y in (r - 1,):
            if 0 <= y < h and 0 <= c < w:
                out[y][c] = 5
        for y in (r - 1, r, r + 1):
            if 0 <= y < h:
                for x in (c - 2, c + 2):
                    if 0 <= x < w:
                        out[y][x] = 2
        # The center vertical segment reaches the marker from the crown.
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        ground_rows.add((r + 2, c))

    # A continuous 2-colored ground line crosses each marker's row; the
